arguments.command:
cd /app; rm -rf /tmp/v; mkdir /tmp/v; 
mk(){ n=$1; mkdir /tmp/v/$n; cp -r quayside /tmp/v/$n/; }
mk key; python3 - <<'E'
p='/tmp/v/key/quayside/dedupe.py';s=open(p).read()
s=s.replace('''    field = "idem_key"
    idem = payload.get(field)''','''    field = "idem" if payload.get("v", 0) >= 3 else "idem_key"
    idem = payload.get(field)''');open(p,'w').write(s)
E
mk schema; python3 - <<'E'
p='/tmp/v/schema/quayside/schema.py';s=open(p).read()
i=s.index('    known');s=s[:i]+'    return None\n';open(p,'w').write(s)
E
mk hb; sed -i 's/cfg.visibility_ms \/\/ 3/job.visibility_ms \/\/ 3/' /tmp/v/hb/quayside/lease.py
mk thr; python3 - <<'E'
p='/tmp/v/thr/quayside/retry.py';s=open(p).read()
s=s.replace('''    msg["failures"] += 1
    if msg["failures"] >= job.max_attempts:
        return ("dead", "attempts-exhausted")
    if outcome == "throttled":
        return ("retry", now + retry_after_ms)
''','''    if outcome == "throttled":
        return ("retry", now + retry_after_ms)
    msg["failures"] += 1
    if msg["failures"] >= job.max_attempts:
        return ("dead", "attempts-exhausted")
''');open(p,'w').write(s)
E
for n in key schema hb thr; do echo == $n; python3 tools/replay.py --since 2027-06-08T14:00:10Z --diff --times --pkg /tmp/v/$n > /tmp/v/$n.out; tail -1 /tmp/v/$n.out; awk '{print $2}' /tmp/v/$n.out | sort | uniq -c|sort -rn|head -5; done

cd /app; cat > deadletter-report.json <<'E'
{"causes": [
{"class":"idempotency","file":"quayside/dedupe.py","line":10,"messages":131,"first":"m0007838"},
{"class":"schema","file":"quayside/schema.py","line":26,"messages":1180,"first":"m0010120"},
{"class":"visibility","file":"quayside/lease.py","line":5,"messages":307,"first":"m0009010"},
{"class":"retry-budget","file":"quayside/retry.py","line":20,"messages":292,"first":"m0007308"}
]}
E
echo '{"status":"success","summary":"Fixed four defects (idem field by schema version, unknown-field schema rejection, heartbeat interval from global instead of per-job visibility, throttled counted as failure); wrote deadletter-report.json."}' > STATUS.json
python3 -m unittest 2>&1 | tail -3
